/* --- 2. 代码块 (Code Blocks) 美化 --- */

/* (1) 代码块大容器 */
pre {
    background-color: #fffaf0 !important; /* 花卉白/奶白底色 */
    border: 2px dashed #99cc99 !important; /* 草绿虚线 */
    border-radius: 10px !important;
    padding: 10px !important;
    margin: 10px 0 !important;

    color: #3D2B1F !important; /* 默认深棕色字 (防止某些代码没高亮时看不清) */
    position: relative;
    overflow-x: auto; /* 允许横向滚动 */
}

/* (2) 代码字体 */
code, pre * {
    font-family: 'Consolas', 'Courier New', monospace !important;
    font-size: 0.9em !important;
    text-shadow: none !important; /* 代码不要阴影，费眼 */
}

/* (3) 代码块顶部的“语言栏” (比如 Copy code 那一行) */
.hljs-header, 
.code-block-header {
    background-color: #e6eed6 !important; /* 浅草绿 */
    border-bottom: 2px dashed #99cc99 !important;
    color: #556b2f !important; /* 橄榄绿文字 */
    border-radius: 8px 8px 0 0 !important;
    margin: -10px -10px 10px -10px !important; /* 抵消 padding */
    padding: 5px 10px !important;
    font-weight: bold;
}


/* --- 3. 表格 (Tables) 美化 --- */

table {
    border-collapse: separate !important;
    border-spacing: 0;
    width: 100%;
    margin: 15px 0;

    /* 香槟色实线外框 */
    border: 2px solid #f7e7ce !important; 
    border-radius: 12px !important; /* 圆角表格 */
    overflow: hidden; /* 确保圆角不被直角内容切掉 */
}

/* 单元格通用 */
th, td {
    padding: 3px 5px !important;
    color: #3D2B1F !important;

    /* 内部网格线：香槟色虚线 */
    border-bottom: 1px dashed #f7e7ce !important;
    border-right: 1px dashed #f7e7ce !important;
}

/* 表头 (Header) */
thead th {
    background-color: #f0f7e6 !important; /* 浅绿背景 */
    color: #a52a2a !important;            /* 棕红标题 */
    font-weight: bold !important;
    border-bottom: 2px solid #f7e7ce !important; /* 表头下划线加粗 */
}

/* 隔行变色 (斑马纹) */
tbody tr:nth-child(even) {
    background-color: rgba(255, 255, 255, 0.4) !important;
}
tbody tr:nth-child(odd) {
    background-color: rgba(255, 255, 255, 0.1) !important;
}

