    color: #ff4500 !important; /* 悬停变橙红 */
    border-bottom-style: solid;
}
/* ============ 🐕 模块七：交互特效与细节完善🐕 ============ */

/* --- 1. 打字机光标特效 (Typewriter Cursor) --- */

/* 定义光标的样子：一个闪烁的草绿色竖线 */
.mes_text:last-child::after {
    content: '';
    display: inline-block;
    width: 8px;  /* 光标宽度 */
    height: 18px; /* 光标高度 */
    background-color: #99cc99; /* 草绿色 */
    margin-left: 5px;
    vertical-align: middle;
    animation: blink-cursor 1s infinite; /* 闪烁动画 */
}

/* 只有当 AI 正在生成内容 (或者最后一条消息) 时才显示 */

@keyframes blink-cursor {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}


/* --- 2. 输入框聚焦动画 (Focus Glow) --- */

/* 当你点击输入框时 */
textarea:focus, 
input[type="text"]:focus, 
input[type="search"]:focus {
    /* 边框变色：变成主题棕黄色 */
    border-color: #b8860b !important;

    /* 发光效果：散发淡淡的香槟色光晕 */
    box-shadow: 0 0 10px rgba(247, 231, 206, 0.8) !important;

    /* 背景稍微变亮 */
    background-color: #fff !important;

    transition: all 0.3s ease-in-out;
}


/* --- 3. 文本选中颜色 (Selection) --- */

/* 选中文字时的背景色和文字颜色 */
::selection {
    background-color: #99cc99 !important; /* 草绿背景 */
    color: #fff !important;               /* 白色文字 */
}
::-moz-selection {
    background-color: #99cc99 !important;
    color: #fff !important;
}


