    background-size: 30px !important;
    background-repeat: no-repeat !important;
    background-position: 10px center !important;
    border-color: #d9534f !important; /* 错误时边框变红 */
}

/* 信息提示 (Info) - 加上天使狗图标 */
#toast-container > .toast-info {
    background-image: url('https://i.postimg.cc/d0ZF2XPj/435ABA5BCE1723D3AAB40466C4BB81E1.gif') !important; /* 天使狗 */
    background-size: 30px !important;
    background-repeat: no-repeat !important;
    background-position: 10px center !important;
}


/* --- 5. 滚动条美化 (Scrollbar) --- */
/* 针对 Chrome / Edge / Safari */

::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
}

/* 滚动条轨道 */
::-webkit-scrollbar-track {
    background: rgba(255, 250, 240, 0.5) !important; /* 半透明奶白 */
    border-radius: 4px !important;
