    border: 2px dashed #b8860b !important; /* 棕黄色虚线 */
    background-color: rgba(255, 250, 240, 0.95) !important; /* 奶白底 */

    /* 2. 🛡️ 防误触与易读性设计 */
    margin-bottom: 10px !important;    /* 增加间距，防止手指粗点错 */
    padding: 10px 10px !important;     /* 增加内边距，让文字呼吸 */
    border-radius: 12px !important;    /* 圆角 */

    /* 3. 文字优化 */
    color: #3D2B1F !important;
    font-weight: bold !important;
    box-shadow: 0 2px 5px rgba(184, 134, 11, 0.15) !important;
    transition: transform 0.2s ease, background-color 0.2s;
}

/* 悬停/点击时的反馈 */
#regex_manager .list-group-item:hover,
#quick-replies-container .list-group-item:hover {
    background-color: #fff8dc !important; /* 悬停变玉米丝色 */
    transform: scale(1.01); /* 微微放大，确认选中感 */
    border-style: solid !important; /* 虚线变实线 */
}

/* ============ 🐶模块九，收藏栏卡牌化美化🐶============ */

/* ============ 1. 列表容器布局 - 左右滑动 ============ */

/* 收藏栏外层容器 */
.hotswap,
#hot-swap-wrapper,
.hot-swap-container {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important; /* 不换行，强制一行排列 */
    overflow-x: auto !important; /* 水平方向可滚动 */
    overflow-y: hidden !important; /* 垂直方向隐藏 */
    gap: 15px !important; /* 卡牌之间的间距 */
    padding: 8px 2px !important; /* 上下留空给贴纸和上浮效果 */
    scroll-behavior: smooth !important; /* 平滑滚动 */
    -webkit-overflow-scrolling: touch !important;
}

/* 美化滚动条 - 横向 */
.hotswap::-webkit-scrollbar {
    height: 1px !important;
}

.hotswap::-webkit-scrollbar-track {
    background: #F5F5DC !important; /* 米色轨道 */
    border-radius: 1px !important;
}

.hotswap::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #D4AF37, #B8860B) !important; /* 金色滑块 */
    border-radius: 1px !important;
}

/* ============ 2. 核心 - 头像容器变成1:1方形卡牌 ============ */

/* 卡牌容器 */
.hotswap .avatar {
    /* 1:1 卡牌比例 */
    width: 40px !important; /* 宽度 */
    height: 40px !important; /* 高度 = 宽度 */
    min-width: 15px !important; /* 防止被挤压 */
    flex-shrink: 0 !important; /* 不允许收缩 */

    /* 金色边框 */
    border: 1px solid #D4AF37 !important;
    box-shadow:
        0 0 0 1px #B8860B, /* 内层深金边 */
        0 2px 1px rgba(0, 0, 0, 0.25) !important; /* 卡牌阴影 */

    /* 圆角矩形 */
    border-radius: 8px !important;

    /* 布局相关 */
    overflow: visible !important; /* 允许贴纸溢出 */
    position: relative !important;

    /* 过渡动画 */
    transition: transform 0.3s ease, box-shadow 0.3s ease !important;

    /* 背景色兜底 */
    background-color: #FFFAF0 !important;
}

/* 卡牌内的图片 */
.hotswap .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important; /* 图片填满卡牌，裁切多余部分 */
    object-position: center top !important; /* 优先显示头部 */
    border-radius: 5px !important; /* 图片圆角略小于边框 */
    display: block !important;
}

/* ============ 3. 鼠标悬停特效 - 卡牌微微上浮 ============ */

.hotswap .avatar:hover {
    transform: translateY(-4px) !important; /* 向上浮动4像素 */
    box-shadow:
        0 0 0 1px #B8860B,
        0 0 2px rgba(212, 175, 55, 0.6), /* 金色光晕 */
        0 2px 2px rgba(0, 0, 0, 0.3) !important; /* 更深的阴影 */
    cursor: pointer !important;
}

/* ============ 🔴 收藏栏卡牌贴图装饰 🔴 ============ */

/* 1. 首先允许卡牌容器"溢出"，这样贴纸才能贴在外面 */
.hotswap .avatar {
    overflow: visible !important;
    position: relative !important;
}

/* 2. 同时，为了保证卡牌本身的圆角不失效，我们需要把圆角加给图片本身 */
.hotswap .avatar img {
    /* 把圆角还给图片，防止溢出显示后变回直角 */
    border-radius: 5px !important;
}

/* 3. 添加贴纸 (利用伪元素) */
.hotswap .avatar::after {
    content: '';
    position: absolute;

    /* 👇 调整贴纸大小 */
    width: 45px;
    height: 45px;

    /* 👇 调整贴纸位置 (这里是右上角可以改 top/left/bottom) */
    top: -15px;    /* 往上提，让它骑在边缘 */
    right: 2px;  /* 往右挪，骑在边缘 */

    /* 👇 皇帝帽子图 */
    background-image: url('https://i.postimg.cc/NjzYrtV4/10D1090357F5495777652AA27481F938.png');

    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    /* 确保贴纸在卡牌上面，且不挡住点击 */
    z-index: 10;
    pointer-events: none;

    /* (可选) 给贴纸加一点阴影 */
    filter: drop-shadow(0 2px 2px rgba(0,0,0,0.3));
}
/* ============ 🐕 模块十，用户人设管理 - 单独背景覆盖 🐕 ============ */

/* 1.用更高优先级覆盖通用背景 */
#persona_drawer,
#persona_drawer.drawer-content,
#persona_drawer > .drawer-content,
.drawer[data-drawer-id="persona"] .drawer-content,
#user_avatar_block,
#persona_management_popup,
#persona_management_drawer,
#persona_management_drawer .drawer-content,
[data-drawer="persona-management"],
[data-drawer="persona-management"] .drawer-content {
    background-image: url('https://i.postimg.cc/P5P7qd3P/retouch_2025122200404673.png') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: local !important;
}

/* 2人设头像容器 - 圆形边框修正版 */
#user_avatar_block .avatar,
#persona_drawer .avatar,
.persona_entry .avatar,
.avatar-container .avatar {
    position: relative !important;
    overflow: visible !important; /* 允许边框溢出 */
}

/* 用伪元素创建圆形图片边框 */
#user_avatar_block .avatar::before,
#persona_drawer .avatar::before,
.persona_entry .avatar::before,
.avatar-container .avatar::before {
    content: '' !important;
    position: absolute !important;

    /* 关键：用正方形保持圆形图片不变形 */
    width: calc(100% + 16px) !important;  /* 比头像大16px */
    height: calc(100% + 16px) !important; /* 宽高相等，保持正方形 */

    /* 居中对齐 */
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;

    /* 圆形边框图片 */
    background-image: url('https://i.postimg.cc/fyjgFKz8/retouch-2025122203132541.png') !important;
    background-size: contain !important; /* 保持图片比例不拉伸 */
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 层级在头像下面 */
    z-index: -1 !important;

    /* 发光效果 */
    filter: drop-shadow(0 0 10px rgba(212, 175, 55, 0.9)) !important;

    pointer-events: none !important;
}

/* 悬停时发光增强 */
#user_avatar_block .avatar:hover::before,
#persona_drawer .avatar:hover::before,
.persona_entry .avatar:hover::before,
.avatar-container .avatar:hover::before {
    filter: drop-shadow(0 0 15px rgba(255, 215, 0, 0.9)) !important;
}

/* 确保头像内容在边框上方 */
#user_avatar_block .avatar > *,
#persona_drawer .avatar > *,
.persona_entry .avatar > *,
.avatar-container .avatar > * {
    position: relative !important;
    z-index: 1 !important;
}
/* ============ 🐶模块十一：弹窗彻底修复 (Nuclear Fix) 🐶============ */

