/* ============ 🖥️ 电脑端底栏宽度修复 🖥️ ============ */
/* 仅在屏幕宽度大于 1000px (电脑端) 时生效，不影响手机 */
@media screen and (min-width: 1000px) {

    /* 1. 强制底栏容器跟随“聊天显示宽度” */
    #form_sheld {
        max-width: var(--sheldWidth) !important; /* 关键：读取酒馆设置的宽度 */
        width: 100% !important;

        /* 强制居中定位 */
        left: 0 !important;
        right: 0 !important;
        margin: 0 auto !important;

        /* 稍微离底部一点距离，不要贴死，更有悬浮感 */
        bottom: 10px !important; 
    }

    /* 2. 确保输入框背景圆角在电脑上不突兀 */
    #send_form {
        border-radius: 15px !important; /* 四个角都变圆 */
        box-shadow: 0 5px 15px rgba(0,0,0,0.1) !important; /* 加点阴影更立体 */
    }
}
